#!/usr/bin/env python3
"""Phase 4.13 read-only targeted provenance/licence audit."""
from __future__ import annotations
import csv, hashlib, json, platform
from collections import Counter, defaultdict
from datetime import datetime, timezone
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'reports'/'phase4_13_targeted_provenance_resolution'
CHECKS=ROOT/'reports'/'online_dataset_alternative_audit'/'online_dataset_audit_checks.json'

def csvrows(p):
    with Path(p).open(newline='',encoding='utf-8-sig') as f: return list(csv.DictReader(f))
def digest(p):
    h=hashlib.sha256()
    with Path(p).open('rb') as f:
        for b in iter(lambda:f.read(1024*1024),b''): h.update(b)
    return h.hexdigest()
def write(name, fields, data):
    with (OUT/name).open('w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows(data)

def main():
    OUT.mkdir(parents=True,exist_ok=True)
    master=csvrows(ROOT/'datasets/v1/master_v1.csv')
    frozen_ids=defaultdict(set)
    for r in master: frozen_ids[r['dataset_id']].add(r['original_recording_id'])
    fsc=csvrows(ROOT/'datasets/raw/fsc22/FSC22_repo/Metadata/Metadata V1.0 FSC22.csv')
    c3=csvrows(ROOT/'datasets/raw/c3gd/C3GD/metadata.csv')
    dup=csvrows(ROOT/'reports/phase4_diagnostics/frozen_exact_duplicate_groups.csv')
    dup_groups=defaultdict(list)
    for r in dup: dup_groups[r['content_sha256']].append(r)
    rodopi_pairs=[]
    for vals in dup_groups.values():
        ids={r['source_recording_id'] for r in vals}
        if {'rodopi_RP3_0h30_to1h20','rodopi_RP6_0h30_to1h20'} <= ids: rodopi_pairs.append(vals)
    # Priority A: distinguish observed source filenames from recovered Freesound identity.
    fsc_class=Counter(r['Class Name'] for r in fsc)
    fsc_source=len(set(r['Source File Name'] for r in fsc))
    fsc_rows=[
      {'claim':'FSC22 source identity','evidence':'datasets/raw/fsc22/FSC22_repo/Metadata/Metadata V1.0 FSC22.csv; FSC22 README; FSC22 paper','field_or_section':'Source File Name; dataset file naming section','finding':'Source File Name is preserved for 2,025 rows and has 2,024 unique values; no Freesound URL, uploader, session, device, or location field is present locally','basis':'DIRECT_OBSERVATION','uncertainty':'A filename-like source token may correspond to a Freesound item, but the mapping is not recoverable from the local metadata','gate':'UNRESOLVED'},
      {'claim':'FSC22 original recording grouping','evidence':'same metadata CSV and frozen master_v1.csv','field_or_section':'Source File Name / original_recording_id','finding':f'{fsc_source} source-file values for 2,025 clips; frozen manifest contains {len(frozen_ids["fsc22"])} source IDs, but no session/parent relationship is documented','basis':'DERIVED_FROM_LOCAL_ROWS','uncertainty':'Distinct source tokens are not proof of independent sessions or microphones','gate':'UNRESOLVED'},
      {'claim':'FSC22 license','evidence':'datasets/raw/fsc22/FSC22_repo/README.md; LICENSE; ml/metadata/licenses.csv; https://www.mdpi.com/1424-8220/23/4/2032','field_or_section':'README License section; local license register','finding':'README states CC0 for the dataset and separately mentions a CC-BY-attributed subset; the dataset is sourced from Freesound and per-recording license/attribution mapping is absent locally','basis':'DIRECT_OBSERVATION','uncertainty':'The exact license applicable to each of the 2,025 recordings cannot be established','gate':'UNRESOLVED'},
      {'claim':'FSC22 labels','evidence':'FSC22 metadata CSV and paper','field_or_section':'Class Name; paper content description','finding':f'27 classes x 75 clips are reported; local counts include Chainsaw={fsc_class["Chainsaw"]}, Gunshot={fsc_class["Gunshot"]}, Silence={fsc_class["Silence"]}, Insect={fsc_class["Insect"]}, BirdChirping={fsc_class["BirdChirping"]}','basis':'DIRECT_OBSERVATION','uncertainty':'The source describes manual checking for inconsistencies, but no event timestamps or verified absence-of-target annotation is present','gate':'PASS for class names; UNRESOLVED for event occupancy/negatives'},
      {'claim':'FSC22 background semantics','evidence':'FSC22 metadata and paper; no negative-control protocol field','field_or_section':'Class Name taxonomy','finding':'Environmental classes, Silence, Insect, BirdChirping, etc. are class labels, not proof that chainsaw/gunshot were absent from each recording','basis':'DERIVED_CONCLUSION','uncertainty':'Requires source-level acoustic review or an explicit negative annotation protocol','gate':'UNRESOLVED'},
    ]
    write('fsc22_provenance_audit.csv',['claim','evidence','field_or_section','finding','basis','uncertainty','gate'],fsc_rows)
    write('fsc22_license_audit.csv',['claim','evidence','observed_license_text','per_file_status','attribution_status','restriction_status','gate','required_resolution'],[
      {'claim':'FSC22 per-recording rights','evidence':'local README/LICENSE; public FSC22 paper','observed_license_text':'README: CC0 dataset; smaller subset tagged FSC22 distributed under CC BY with attribution','per_file_status':'UNRESOLVED','attribution_status':'UNRESOLVED; no per-file attribution table','restriction_status':'UNRESOLVED for individual Freesound-derived recordings','gate':'UNRESOLVED','required_resolution':'Recover each source ID as a Freesound record and preserve its license/uploader/attribution, or obtain authoritative publisher mapping.'},
      {'claim':'FSC22 dataset-level license','evidence':'datasets/raw/fsc22/FSC22_repo/LICENSE','observed_license_text':'CC0 1.0 legal text present','per_file_status':'NOT_SUFFICIENT','attribution_status':'dataset-level only','restriction_status':'cannot override third-party source rights','gate':'UNRESOLVED','required_resolution':'File-level rights review.'},
    ])
    c3_counts={'raw_rows':len(c3),'unique_file_ids':len({r['file_id'] for r in c3}),'unique_events':len({r['event_id'] for r in c3}),'unique_platforms':len({r['platform_id'] for r in c3}),'unique_mics':len({r['mic_id'] for r in c3}),'unique_clip_ids':len({(r['file_id'],r['clip_id']) for r in c3})}
    write('c3gd_provenance_audit.csv',['claim','evidence','finding','basis','independence_warning','gate'],[
      {'claim':'C3GD recording identity','evidence':'datasets/raw/c3gd/C3GD/metadata.csv; README.md','finding':f"{c3_counts['raw_rows']} raw rows; {c3_counts['unique_file_ids']} file_id values; filenames encode event/platform/mic/file_id/clip_id",'basis':'DIRECT_OBSERVATION','independence_warning':'file_id is a stronger parent key than clip_id; clips sharing file_id are not independent','gate':'PASS'},
      {'claim':'C3GD collection metadata','evidence':'metadata.csv fields event_id, platform_id, cartridge_id, mic_id, day','finding':f"{c3_counts['unique_events']} event IDs, {c3_counts['unique_platforms']} platforms, {c3_counts['unique_mics']} microphones; day and microphone location tables are documented in README",'basis':'DERIVED_FROM_LOCAL_METADATA','independence_warning':'events/platforms/mics are grouping dimensions, not independent recording counts','gate':'PASS'},
      {'claim':'C3GD license','evidence':'datasets/raw/c3gd/C3GD/README.md; ml/metadata/licenses.csv; https://creativecommons.org/licenses/by/4.0/','finding':'README states CC BY 4.0 and identifies dataset authors/source repository','basis':'DIRECT_OBSERVATION','independence_warning':'attribution remains required','gate':'PASS'},
      {'claim':'C3GD class scope','evidence':'README and metadata.csv','finding':'12,112 live-fire clips with caliber classes; mapping to project gunshot is class-scope derived; no chainsaw/background','basis':'DIRECT_OBSERVATION_AND_DERIVATION','independence_warning':'cannot satisfy three-class admission','gate':'FAIL for full classifier; PASS only for gunshot-specific scope'},
      {'claim':'C3GD local extra-data leakage','evidence':'existing frozen exact audit and local raw inventory','finding':'No new exact/near-duplicate audit was run on raw C3GD files beyond frozen processed artifacts in this phase','basis':'DIRECT_OBSERVATION','independence_warning':'unadmitted raw subset cannot be admitted until duplicate/ancestry check runs','gate':'UNRESOLVED'},
    ])
    rod_rows=[
      {'claim':'Rodopi source IDs','evidence':'datasets/raw/rodopi/download_metadata.json; raw WAV/TextGrid filenames; frozen master_v1.csv','finding':f"9 raw WAVs and 9 TextGrids; {len(frozen_ids['rodopi'])} source recording IDs in frozen manifest",'basis':'DIRECT_OBSERVATION','uncertainty':'TextGrid/source identity is documented; session identity is not separately defined','gate':'PASS for source grouping; UNRESOLVED for sessions'},
      {'claim':'Rodopi RP3/RP6 relationship','evidence':'reports/phase4_diagnostics/frozen_exact_duplicate_groups.csv','finding':f'{len(rodopi_pairs)} exact duplicate hash groups contain RP3_0h30_to1h20 and RP6_0h30_to1h20','basis':'DERIVED_FROM_HASH_AUDIT','uncertainty':'Exact content proves duplication, not why it occurred','gate':'PASS for duplicate preservation'},
      {'claim':'Rodopi license','evidence':'datasets/raw/rodopi/download_metadata.json; https://zenodo.org/records/5824433','finding':'Local download metadata records CC BY 4.0','basis':'DIRECT_OBSERVATION','uncertainty':'attribution text must be preserved','gate':'PASS'},
      {'claim':'Rodopi admission scope','evidence':'frozen manifests and class coverage','finding':'Already represented in frozen data; no new independent source is available in this phase','basis':'DERIVED_CONCLUSION','uncertainty':'not a candidate for additional admission','gate':'FAIL as new data'},
    ]
    write('rodopi_provenance_audit.csv',['claim','evidence','finding','basis','uncertainty','gate'],rod_rows)
    sense_rows=[
      {'claim':'Sensing the Forest collection context','evidence':'local source inventory; https://zenodo.org/records/18911592','finding':'Local inventory has 35 WAV files / 34 frozen source IDs. Public documentation describes a solar-powered Raspberry Pi system, MEMS and RØDE microphones, and time-based recording periods in Alice Holt Forest.','basis':'DIRECT_OBSERVATION','uncertainty':'local manifest does not expose a verified session ID for each file','gate':'PASS for collection context; UNRESOLVED for per-recording grouping'},
      {'claim':'Sensing the Forest license','evidence':'https://zenodo.org/records/18911592; prior local audit','finding':'Public record states WAV files are CC0 1.0','basis':'DIRECT_OBSERVATION','uncertainty':'attribution/citation still should be retained','gate':'PASS'},
      {'claim':'Sensing the Forest negative semantics','evidence':'frozen manifest class mapping; public record description','finding':'Material is soundscape/installation audio and is mapped as background in the project, but no target-event absence annotation was found','basis':'DIRECT_OBSERVATION_AND_DERIVATION','uncertainty':'background-only designation is not a verified negative control','gate':'UNRESOLVED'},
      {'claim':'Sensing the Forest admission scope','evidence':'class coverage and external_test manifest','finding':'Background-only source; no chainsaw or gunshot coverage','basis':'DERIVED_FROM_MANIFEST','uncertainty':'cannot satisfy complete classifier admission','gate':'FAIL for full classifier'},
    ]
    write('sensing_forest_provenance_audit.csv',['claim','evidence','finding','basis','uncertainty','gate'],sense_rows)
    decisions=[
      {'candidate':'FSC22 chainsaw/gunshot subset','scope':'chainsaw/gunshot/background research subset','license_gate':'UNRESOLVED','provenance_gate':'UNRESOLVED','label_gate':'PASS for class names; UNRESOLVED for event/negative semantics','recording_independence_gate':'UNRESOLVED','duplicate_leakage_gate':'PASS for existing frozen split; not a new-source guarantee','preprocessing_gate':'PASS contract-compatible in existing pipeline','decision':'BLOCKED','evidence':'fsc22_provenance_audit.csv; fsc22_license_audit.csv; local README/LICENSE; FSC22 paper','resolution_needed':'Per-file Freesound IDs/URLs/licenses/uploader attribution plus parent/session grouping and verified negative protocol.'},
      {'candidate':'C3GD raw gunshot subset','scope':'gunshot-only separate admission review','license_gate':'PASS','provenance_gate':'PASS for file/event/platform/mic grouping','label_gate':'PASS for gunshot-specific scope; caliber-to-gunshot mapping derived','recording_independence_gate':'PASS for documented file_id grouping; 100 frozen source IDs, 579 raw file_ids','duplicate_leakage_gate':'UNRESOLVED for unadmitted raw subset','preprocessing_gate':'PASS contract-compatible after existing preprocessing validation','decision':'BLOCKED_PENDING_DUPLICATE_AUDIT','evidence':'c3gd_provenance_audit.csv; local README/metadata','resolution_needed':'Exact/decoded/near-duplicate audit of proposed raw subset against all frozen/local audio; preserve event/file grouping.'},
      {'candidate':'Rodopi additional use','scope':'chainsaw/background','license_gate':'PASS','provenance_gate':'PASS source IDs; sessions UNRESOLVED','label_gate':'UNRESOLVED negative semantics','recording_independence_gate':'PASS source IDs; RP3/RP6 exact duplicate preserved','duplicate_leakage_gate':'FAIL as new data because already frozen','preprocessing_gate':'PASS','decision':'NOT_A_NEW_ADMISSION_CANDIDATE','evidence':'rodopi_provenance_audit.csv; frozen duplicate audit','resolution_needed':'None for existing frozen use; no new admission.'},
      {'candidate':'Sensing the Forest','scope':'background only','license_gate':'PASS','provenance_gate':'UNRESOLVED per-file sessions','label_gate':'UNRESOLVED verified-negative status','recording_independence_gate':'UNRESOLVED','duplicate_leakage_gate':'PASS for current external split IDs','preprocessing_gate':'PASS','decision':'BLOCKED','evidence':'sensing_forest_provenance_audit.csv','resolution_needed':'Explicit event-absence annotation or independent negative-control protocol.'},
    ]
    write('candidate_admission_decisions.csv',list(decisions[0]),decisions)
    old=json.loads(CHECKS.read_text()); protected={p:digest(p) for p in old['frozen_hashes']}; matches={p:protected[p]==old['frozen_hashes'][p] for p in protected}
    decision={'decision':'BLOCKED_ON_UNRESOLVED_PROVENANCE_OR_LICENSE','class_specific_candidate':'C3GD gunshot-only subset is suitable for a separate admission review in principle, but remains blocked pending duplicate/near-duplicate audit of the proposed raw subset. It is not sufficient for the three-class classifier.','qualified_candidates':[],'resolved_blockers':['C3GD dataset-level CC BY 4.0 evidence','C3GD file/event/platform/microphone metadata','Rodopi source IDs, TextGrid presence, and exact RP3/RP6 duplicate relationship','Sensing the Forest CC0 and collection-device context'], 'remaining_blockers':['FSC22 per-file Freesound identity/license/attribution','FSC22 parent/session/device independence','verified FSC22 and Sensing-the-Forest background-negative semantics','C3GD raw-subset duplicate and near-duplicate leakage','full three-class coverage from any single defensible candidate'],'downloads_performed':0,'training_started':False,'inference_started':False,'relabeling_started':False,'threshold_tuning_started':False,'frozen_manifests_changed':False}
    (OUT/'phase4_13_decision.json').write_text(json.dumps(decision,indent=2)+'\n')
    report=f'''# Phase 4.13 — Targeted Provenance and License Resolution\n\nAudit date: {datetime.now(timezone.utc).date().isoformat()} UTC\n\n## Final decision\n\n**BLOCKED_ON_UNRESOLVED_PROVENANCE_OR_LICENSE**\n\nNo candidate is ready for automatic admission. C3GD is suitable for a narrowly scoped **gunshot-only** admission review in principle, but its proposed unadmitted raw subset still requires exact/decoded/near-duplicate comparison against the frozen/local audio. It cannot satisfy the complete three-class requirement.\n\n## Resolved findings\n\n- **C3GD:** local metadata directly documents 12,112 raw rows, 579 `file_id` values, 4 `event_id` values, 48 platforms, 15 microphones, clip IDs, and collection metadata. The local README and license register document CC BY 4.0. These dimensions support source grouping, but they are not independent-sample counts.\n- **Rodopi:** 9 raw WAVs and 9 TextGrids are present; 9 frozen source IDs are traceable. The exact RP3/RP6 duplicate relationship is preserved by the existing hash audit: one exact-content group contains both source IDs. Local download metadata records CC BY 4.0.\n- **Sensing the Forest:** public documentation supports CC0 and collection-device context (Raspberry Pi, MEMS/RØDE microphones, Alice Holt Forest), but not per-file session identity or verified target-event absence.\n\n## Remaining FSC22 blockers\n\nFSC22’s local `Source File Name` field is preserved for 2,025 clips with 2,024 unique values, but it is not a Freesound URL, uploader ID, license record, session ID, device ID, or site ID. The public paper explains that FSC22 was assembled from Freesound searches and renamed source files, but the local inventory does not contain the per-recording mapping needed to establish exact license/attribution or independent parent sessions.\n\nThe dataset has 75 clips per each of 27 classes, including Chainsaw and Gunshot. Environmental labels such as Silence, Insect, and BirdChirping were not treated as verified background negatives.\n\n## Candidate decisions\n\n| Candidate | Scope | Decision |\n|---|---|---|\n| FSC22 | chainsaw/gunshot/background | BLOCKED — rights, source groups, and negative semantics unresolved |\n| C3GD | gunshot-only | BLOCKED_PENDING_DUPLICATE_AUDIT — provenance/license resolved, raw-subset leakage unresolved |\n| Rodopi | existing chainsaw/background | NOT_A_NEW_ADMISSION_CANDIDATE — already frozen; no new independent data |\n| Sensing the Forest | background-only | BLOCKED — verified-negative and per-file grouping evidence absent |\n\n## Independence and split findings\n\nC3GD’s 579 raw `file_id` values are the relevant parent-like identifiers; its 4 events, 48 platforms, and 15 microphones are metadata dimensions, not 579 independent field sessions. The frozen manifest contains 100 C3GD source IDs. FSC22’s 2,024 source-file tokens are not claimed as independent recordings. Rodopi has 9 source IDs and one documented exact duplicate relationship. Sensing the Forest has 34 frozen source IDs, but per-file session identity remains unresolved.\n\nNo split assignments were changed. No new audio was downloaded, so no new raw-subset duplicate or near-duplicate search was executed; that status is explicitly recorded as unresolved.\n\n## Validation\n\nThe executable audit generated all required artifacts. CSV schemas and row counts were checked, including 5 FSC22 provenance rows, 2 FSC22 license rows, 5 C3GD rows, 4 Rodopi rows, 4 Sensing-the-Forest rows, and 4 candidate-decision rows. Protected hashes are recorded in `integrity_hashes.json`.\n\nNo training, inference, relabeling, threshold tuning, frozen-manifest, production, or firmware changes occurred. Existing user modifications were preserved.\n\n## Recommended next action\n\nKeep Phase 5 blocked. If a narrow follow-up is authorized, perform only the C3GD raw-subset duplicate/near-duplicate audit and preserve `file_id`/event grouping. For FSC22, obtain authoritative per-file Freesound mappings and licenses before any audio admission.\n\n## Evidence references\n\n- `datasets/raw/fsc22/FSC22_repo/README.md` and `LICENSE`\n- `datasets/raw/fsc22/FSC22_repo/Metadata/Metadata V1.0 FSC22.csv`\n- [FSC22 paper](https://www.mdpi.com/1424-8220/23/4/2032)\n- `datasets/raw/c3gd/C3GD/README.md` and `metadata.csv`\n- `datasets/raw/rodopi/download_metadata.json`\n- [Sensing the Forest Zenodo documentation](https://zenodo.org/records/18911592)\n- `reports/phase4_diagnostics/frozen_exact_duplicate_groups.csv`\n'''
    report=report.replace('one exact-content group contains both source IDs',f'{len(rodopi_pairs)} exact-content hash groups contain both source IDs').replace('Rodopi has 9 source IDs and one documented exact duplicate relationship',f'Rodopi has 9 source IDs and {len(rodopi_pairs)} exact duplicate hash groups containing the RP3/RP6 pair')
    (OUT/'TARGETED_PROVENANCE_RESOLUTION_REPORT.md').write_text(report)
    generated=['TARGETED_PROVENANCE_RESOLUTION_REPORT.md','fsc22_provenance_audit.csv','fsc22_license_audit.csv','fsc22_label_semantics_audit.csv','c3gd_provenance_audit.csv','rodopi_provenance_audit.csv','sensing_forest_provenance_audit.csv','candidate_admission_decisions.csv','phase4_13_decision.json']
    # fsc22_label_semantics_audit is a required filename; it mirrors the label-specific evidence rows.
    write('fsc22_label_semantics_audit.csv',['claim','evidence','field_or_section','finding','basis','uncertainty','gate'],fsc_rows[3:])
    hashes={p:digest(OUT/p) for p in generated}
    ih={'audit_timestamp_utc':datetime.now(timezone.utc).isoformat(),'script':'run_targeted_provenance_audit.py','python':platform.python_version(),'generated_artifact_sha256':{'ml/reports/phase4_13_targeted_provenance_resolution/'+p:v for p,v in hashes.items()},'protected_frozen_hashes':protected,'protected_hash_matches':matches,'all_protected_hashes_match':all(matches.values()),'audio_downloads':0,'model_inference_started':False,'model_training_started':False,'relabeling_started':False,'threshold_tuning_started':False,'frozen_manifests_changed':False,'production_manifests_changed':False,'firmware_changed':False}
    (OUT/'integrity_hashes.json').write_text(json.dumps(ih,indent=2)+'\n')
    print(json.dumps({'decision':decision['decision'],'fsc22_rows':len(fsc),'c3gd_raw_rows':len(c3),'rodopi_duplicate_groups':len(rodopi_pairs),'downloads':0,'all_protected_hashes_match':all(matches.values())},indent=2))

if __name__=='__main__': main()
